<?php namespace App\Http\Controllers; use App\Http\Requests\FamilyMemberRequest; use App\Models\{FamilyMember,User}; use Illuminate\Http\Request; class FamilyController extends Controller { public function index(Request $r){return FamilyMember::with('member:id,name,email')->where('owner_id',$r->user()->id)->get();} public function store(FamilyMemberRequest $r){$m=User::findOrFail($r->member_id); if($m->role!=='owner') return response()->json(['message'=>'Family members must have an owner role.'],422); return response()->json(FamilyMember::create(['owner_id'=>$r->user()->id,'member_id'=>$m->id,'permissions'=>$r->permissions]),201);} public function update(Request $r,FamilyMember $familyMember){abort_unless($familyMember->owner_id===$r->user()->id,403);$familyMember->update($r->validate(['status'=>'required|in:pending,accepted,rejected','permissions'=>'required|in:view,manage']));return $familyMember->fresh('member');} public function destroy(Request $r,FamilyMember $familyMember){abort_unless($familyMember->owner_id===$r->user()->id,403);$familyMember->delete();return response()->noContent();} }